    rows = [set() for _ in range(9)]
    cols = [set() for _ in range(9)]
    blocks = [[set() for _ in range(3)] for _ in range(3)]

    for i in range(9):
        for j in range(9):
            if board[i][j] != 'x':
                num = int(board[i][j])
                if num in rows[i]:
                    return -1
                rows[i].add(num)
                if num in cols[j]:
                    return -1
                cols[j].add(num)
                block_row, block_col = i // 3, j // 3
                if num in blocks[block_row][block_col]:
                    return -1
                blocks[block_row][block_col].add(num)

    changes = []
    for i in range(9):
        for j in range(9):
            if board[i][j] == 'x':
                continue
            num = int(board[i][j])
            for candidate in range(1, 10):
                if candidate not in rows[i] and candidate not in cols[j]:
                    block_row, block_col = i // 3, j // 3
                    if candidate not in blocks[block_row][block_col]:
                        rows[i].add(candidate)
                        cols[j].add(candidate)
                        blocks[block_row][block_col].add(candidate)
                        changes.append((i, j, candidate))
                        break

    if len(changes) > 9:
        return -1

    for i, j, candidate in changes:
        board[i] = board[i][:j] + str(candidate) + board[i][j+1:]

    return '\n'.join(board)

