def make_anti_sudoku(sudoku):
    def has_duplicates(row):
        return len(set(row)) != len(row)

    def find_first_duplicate_index(arr):
        count = {}
        for i, x in enumerate(arr):
            if x in count:
                return i - count[x]
            count[x] = i
        return None

    def modify_row(row):
        dup_index = find_first_duplicate_index(row)
        if dup_index is None:
            dup_index = 0
        row[dup_index] = str((int(row[dup_index]) % 9) + 1 if int(row[dup_index]) > 1 else 2)

    def modify_column(grid, col_index):
        col = [grid[row][col_index] for row in range(9)]
        dup_index = find_first_duplicate_index(col)
        if dup_index is None:
            dup_index = 0
        grid[dup_index][col_index] = str((int(grid[dup_index][col_index]) % 9) + 1 if int(grid[dup_index][col_index]) > 1 else 2)

    def modify_block(grid, block_row, block_col):
        block = []
        for i in range(block_row * 3, (block_row + 1) * 3):
            for j in range(block_col * 3, (block_col + 1) * 3):
                block.append(grid[i][j])
        dup_index = find_first_duplicate_index(block)
        if dup_index is None:
            dup_index = 0
        row_index = block_row * 3 + dup_index // 3
        col_index = block_col * 3 + dup_index % 3
        grid[row_index][col_index] = str((int(grid[row_index][col_index]) % 9) + 1 if int(grid[row_index][col_index]) > 1 else 2)

    grid = [list(row) for row in sudoku.split('\n')]

    # Check rows and modify them if necessary
    for i in range(9):
        if has_duplicates(grid[i]):
            continue
        modify_row(grid[i])

    # Check columns and modify them if necessary
    for j in range(9):
        if has_duplicates([grid[i][j] for i in range(9)]):
            continue
        modify_column(grid, j)

    # Check blocks and modify them if necessary
    for i in range(3):
        for j in range(3):
            if has_duplicates([grid[m][n] for m in range(i * 3, (i + 1) * 3) for n in range(j * 3, (j + 1) * 3)]):
                continue
            modify_block(grid, i, j)

    return '\n'.join(''.join(row) for row in grid)

